77: // CDP WebSocket Client
78: class CdpClient {
79:   constructor(wsUrl) {
80:     this.wsUrl = wsUrl;
81:     this.ws = null;
82:     this.id = 1;
83:     this.pending = new Map();
84:     this.eventListeners = new Map();
85:   }
86: 
87:   connect() {
88:     return new Promise((resolve, reject) => {
89:       this.ws = new WebSocket(this.wsUrl);
90:       this.ws.onopen = () => resolve();
91:       this.ws.onerror = (err) => reject(err);
92:       this.ws.onclose = () => {
93:         for (const [id, { reject: rej }] of this.pending.entries()) {
94:           rej(new Error('WebSocket closed'));
95:         }
96:         this.pending.clear();
97:       };
98:       this.ws.onmessage = (event) => {
99:         try {
100:           const msg = JSON.parse(event.data);
101:           if (msg.id && this.pending.has(msg.id)) {
102:             const { resolve: res, reject: rej } = this.pending.get(msg.id);
103:             this.pending.delete(msg.id);
104:             if (msg.error) rej(new Error(msg.error.message || JSON.stringify(msg.error)));
105:             else res(msg.result);
106:           } else if (msg.method) {
107:             const handlers = this.eventListeners.get(msg.method) || [];
108:             handlers.forEach(fn => fn(msg.params));
109:           }
110:         } catch (e) {
111:           console.error('CDP message parse error:', e);
112:         }
113:       };
114:     });
115:   }
116: 
117:   send(method, params = {}) {
118:     return new Promise((resolve, reject) => {
119:       if (!this.ws || this.ws.readyState !== 1) {
120:         return reject(new Error('WebSocket is not open'));
121:       }
122:       const msgId = this.id++;
123:       this.pending.set(msgId, { resolve, reject });
124:       this.ws.send(JSON.stringify({ id: msgId, method, params }));
125:     });
126:   }
127: 
128:   on(method, handler) {
129:     if (!this.eventListeners.has(method)) {
130:       this.eventListeners.set(method, []);
131:     }
132:     this.eventListeners.get(method).push(handler);
133:   }
134: 
135:   async evaluate(expression, awaitPromise = true) {
136:     const res = await this.send('Runtime.evaluate', {
137:       expression,
138:       awaitPromise,
139:       returnByValue: true
140:     });
141:     if (res.exceptionDetails) {
142:       throw new Error(
143:         res.exceptionDetails.exception
144:           ? (res.exceptionDetails.exception.description || res.exceptionDetails.exception.value)
145:           : 'Evaluation exception'
146:       );
147:     }
148:     return res.result ? res.result.value : undefined;
149:   }
150: 
151:   close() {
152:     if (this.ws) {
153:       try { this.ws.close(); } catch (_) {}
154:       this.ws = null;
155:     }
156:   }
157: }
