159: // Helper to discover and connect to WAM CDP target
160: async function connectToWam(appId = CONFIG.appId, maxRetries = 12, delayMs = 1000) {
161:   for (let attempt = 1; attempt <= maxRetries; attempt++) {
162:     try {
163:       const pages = await fetch(`http://${CONFIG.tvIp}:${CONFIG.devtoolsPort}/json`).then(r => r.json());
164:       const target = pages.find(p => p.url && p.url.includes(appId));
165:       if (target && target.webSocketDebuggerUrl) {
166:         const client = new CdpClient(target.webSocketDebuggerUrl);
167:         await client.connect();
168:         await client.send('Runtime.enable');
169:         await client.send('Page.enable');
170:         return { client, target };
171:       }
172:     } catch (_) {}
173:     if (attempt < maxRetries) await sleep(delayMs);
174:   }
175:   throw new Error(`Failed to connect to WAM DevTools target for ${appId} after ${maxRetries} attempts`);
176: }
